class SumTask extends RecursiveTask<Long> {
    private final long[] a; private final int lo, hi;
    SumTask(long[] a, int lo, int hi) { this.a = a; this.lo = lo; this.hi = hi; }
    protected Long compute() {
        if (hi - lo < 4096) return sumSequential(a, lo, hi);      // base case
        int mid = (lo + hi) >>> 1;
        SumTask left = new SumTask(a, lo, mid);
        left.fork();                                              // fork
        long right = new SumTask(a, mid, hi).compute();           // work here
        return left.join() + right;                               // join + combine
    }
}

