CompletableFuture<Long> solve(long[] a, int lo, int hi) {
    if (hi - lo < 4096)                                   // base case
        return CompletableFuture.completedFuture(sumSequential(a, lo, hi));
    int mid = (lo + hi) >>> 1;
    return solve(a, lo, mid)
        .thenCombine(solve(a, mid, hi), Long::sum);        // join + combine
}

